using System.Text.Json;using Servicio.RetazoMarket.Business.DTOs.Personalizacion;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;
namespace Servicio.RetazoMarket.Business.Services;
public class PersonalizacionService:IPersonalizacionService {private readonly IPersonalizacionDataService _data;private readonly IProductoDataService _productos;private readonly IMaterialDataService _materiales;public PersonalizacionService(IPersonalizacionDataService data,IProductoDataService productos,IMaterialDataService materiales)=>(_data,_productos,_materiales)=(data,productos,materiales);public async Task<PersonalizacionResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _data.ObtenerPorIdAsync(id,ct);return m is null?null:PersonalizacionBusinessMapper.ToResponse(m);}public async Task<IReadOnlyList<PersonalizacionResponse>> ObtenerPorProductoAsync(int id,CancellationToken ct=default)=>(await _data.ObtenerPorProductoAsync(id,ct)).Select(PersonalizacionBusinessMapper.ToResponse).ToList();public async Task<PersonalizacionResponse> CrearAsync(CrearPersonalizacionRequest r,CancellationToken ct=default){var e=PersonalizacionValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await ProductoPersonalizable(r.id_producto,ct);if(r.tipo_valor.Trim().ToUpperInvariant()=="MATERIAL")r.valores_json=await NormalizarMateriales(r.valores_json,ct);return PersonalizacionBusinessMapper.ToResponse(await _data.CrearAsync(PersonalizacionBusinessMapper.ToDataModel(r),ct));}public async Task<PersonalizacionResponse?> ActualizarAsync(ActualizarPersonalizacionRequest r,CancellationToken ct=default){var e=PersonalizacionValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await ProductoPersonalizable(r.id_producto,ct);if(r.tipo_valor.Trim().ToUpperInvariant()=="MATERIAL")r.valores_json=await NormalizarMateriales(r.valores_json,ct);var m=await _data.ActualizarAsync(PersonalizacionBusinessMapper.ToDataModel(r),ct);return m is null?null:PersonalizacionBusinessMapper.ToResponse(m);}private async Task ProductoPersonalizable(int id,CancellationToken ct){var p=await _productos.ObtenerPorIdAsync(id,ct);if(p is null||p.es_personalizable!="S")throw new ValidationException("El producto no existe o no está marcado como personalizable.");}private async Task<JsonElement> NormalizarMateriales(JsonElement json,CancellationToken ct){var opciones=new List<Dictionary<string,object>>();foreach(var id in PersonalizacionValidator.ObtenerMateriales(json)){var m=await _materiales.ObtenerPorIdAsync(id,ct);if(m is null||m.mat_estado!="ACT")throw new ValidationException($"El material {id} no existe o está inactivo.");var original=json.GetProperty("opciones").EnumerateArray().First(x=>x.GetProperty("id_material").GetInt32()==id);var item=new Dictionary<string,object>{{"id_material",id},{"nombre",m.mat_nombre}};if(original.TryGetProperty("costo_adicional",out var costo))item["costo_adicional"]=costo.GetDecimal();opciones.Add(item);}return JsonSerializer.SerializeToElement(new{version=1,requerido=json.GetProperty("requerido").GetBoolean(),opciones});}}
